from pathlib import Path

import pandas as pd
import yaml

ROOT = next(p for p in [Path.cwd(), *Path.cwd().parents] if (p / "_quarto.yml").exists())
PROC = ROOT / "data" / "processed"
DEDUP = PROC / "deduplicated_records.csv"
INCLUDED = PROC / "included_reports.csv"

TABLES = yaml.safe_load((ROOT / "codebook.yml").read_text(encoding="utf-8"))["tables"]
for t in TABLES.values():
    for v in t["variables"]:
        v["values"] = v.get("values", [])
        if not all(isinstance(x, str) for x in v["values"]):
            raise ValueError(f'codebook.yml: the values of {v["name"]} must be text. Put quotes around values such as "yes", "no", and "1".')


def load(name):
    t = TABLES[name]
    path = ROOT / t["file"]
    cols = [v["name"] for v in t["variables"]]
    if not path.exists():
        return pd.DataFrame(columns=cols)
    df = pd.read_csv(path, dtype=str).fillna("")
    df.columns = [c.strip().lower() for c in df.columns]
    absent = [c for c in cols if c not in df.columns]
    if absent:
        raise ValueError(f"{path.name} is missing column(s): {', '.join(absent)}")
    return df[cols].apply(lambda s: s.str.strip())


def sample(values, n=5):
    values = sorted(set(map(str, values)))
    return ", ".join(values[:n]) + (f" and {len(values) - n} more" if len(values) &gt; n else "")


def lines(mask):
    # Line numbers in the CSV file: the header is line 1.
    numbers = sorted(i + 2 for i in mask[mask].index)
    return ", ".join(map(str, numbers[:5])) + (f" and {len(numbers) - 5} more" if len(numbers) &gt; 5 else "")


sources, factors = load("sources"), load("factors")
